"use client";

import { useCallback, useRef, useState } from "react";
import {
  DEFAULT_STORY_COMPOSER_LABELS,
  type PublishFields,
  type PublishMetadata,
  type PublishResult,
  type ResolvedStoryComposerLabels,
  type Uploader,
} from "../types";

export type UploadStatus =
  | "idle"
  | "uploading"
  | "done"
  | "error"
  | "cancelled";

/** The label keys the uploader's own error messages come from. */
export type UploaderMessages = Pick<
  ResolvedStoryComposerLabels,
  | "uploadErrorNoDestination"
  | "uploadErrorHttp"
  | "uploadErrorNetwork"
  | "uploadErrorBadResponse"
  | "uploadCancelled"
>;

export interface UseImageUploaderOptions {
  /** Server endpoint for default POST FormData upload (Q-P6a). */
  uploadUrl?: string;
  /** Extra FormData fields appended to every request. */
  uploadFields?: Record<string, string>;
  /** Custom uploader — wins over uploadUrl when both are set. */
  uploader?: Uploader;
  /** Localized error messages (the component passes its resolved labels). Default: English. */
  messages?: UploaderMessages;
}

export interface UseImageUploaderResult {
  status: UploadStatus;
  /** 0..1 — determinate when XMLHttpRequest reports lengthComputable. */
  progress: number;
  error: Error | null;
  upload: (
    blob: Blob,
    metadata: PublishMetadata,
    fields?: PublishFields,
  ) => Promise<PublishResult>;
  cancel: () => void;
  reset: () => void;
}

/**
 * Default POST FormData uploader (Q-P6a) + escape hatch for signed-URL flows.
 *
 * XMLHttpRequest, not fetch — fetch lacks upload-progress events in browsers,
 * which the publishing overlay needs for a determinate progress bar.
 *
 * Publish fields (caption + host fields) are appended to the FormData next to
 * `uploadFields`: strings as-is, everything else `JSON.stringify`-ed. A custom
 * `uploader` receives them as its third argument instead.
 */
export function useImageUploader(
  options: UseImageUploaderOptions,
): UseImageUploaderResult {
  const { uploadUrl, uploadFields, uploader } = options;
  const messages = options.messages ?? DEFAULT_STORY_COMPOSER_LABELS;
  const [status, setStatus] = useState<UploadStatus>("idle");
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<Error | null>(null);
  const xhrRef = useRef<XMLHttpRequest | null>(null);
  const warnedKeysRef = useRef(new Set<string>());

  const reset = useCallback(() => {
    setStatus("idle");
    setProgress(0);
    setError(null);
  }, []);

  const cancel = useCallback(() => {
    xhrRef.current?.abort();
    xhrRef.current = null;
    setStatus("cancelled");
  }, []);

  const upload = useCallback(
    async (
      blob: Blob,
      metadata: PublishMetadata,
      fields: PublishFields = {},
    ): Promise<PublishResult> => {
      setStatus("uploading");
      setProgress(0);
      setError(null);

      // Custom uploader path (S3 pre-signed PUT / Cloudinary / Mux).
      if (uploader) {
        try {
          const result = await uploader(blob, metadata, fields);
          setStatus("done");
          setProgress(1);
          return result;
        } catch (err) {
          const e = err instanceof Error ? err : new Error(String(err));
          setStatus("error");
          setError(e);
          throw e;
        }
      }

      // Default POST FormData path.
      if (!uploadUrl) {
        const e = new Error(messages.uploadErrorNoDestination);
        setStatus("error");
        setError(e);
        throw e;
      }

      return new Promise<PublishResult>((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhrRef.current = xhr;
        xhr.open("POST", uploadUrl, true);

        xhr.upload.onprogress = (ev) => {
          if (ev.lengthComputable) {
            setProgress(ev.loaded / ev.total);
          }
        };

        xhr.onload = () => {
          xhrRef.current = null;
          if (xhr.status >= 200 && xhr.status < 300) {
            try {
              const text = xhr.responseText;
              const parsed: PublishResult = text
                ? JSON.parse(text)
                : { url: "" };
              if (!parsed.url) {
                // Allow servers that return 200 without a body, but caller
                // probably wants the URL — leave it blank and proceed.
                parsed.url = "";
              }
              setStatus("done");
              setProgress(1);
              resolve(parsed);
            } catch (parseErr) {
              // Always the localized message; the parser's own error is the cause.
              const e = new Error(messages.uploadErrorBadResponse, {
                cause: parseErr,
              });
              setStatus("error");
              setError(e);
              reject(e);
            }
          } else {
            const e = new Error(messages.uploadErrorHttp(xhr.status));
            setStatus("error");
            setError(e);
            reject(e);
          }
        };

        xhr.onerror = () => {
          xhrRef.current = null;
          const e = new Error(messages.uploadErrorNetwork);
          setStatus("error");
          setError(e);
          reject(e);
        };

        xhr.onabort = () => {
          xhrRef.current = null;
          // status already set to "cancelled" by cancel(). Reject so awaiting
          // callers don't hang forever — DOMException/AbortError mirrors the
          // fetch abort contract, so callers can filter it from real errors.
          reject(new DOMException(messages.uploadCancelled, "AbortError"));
        };

        const form = new FormData();
        const ext = blob.type.includes("webm")
          ? "webm"
          : blob.type.includes("mp4")
            ? "mp4"
            : blob.type.includes("png")
              ? "png"
              : "jpg";
        form.append(
          "file",
          blob,
          `story-${Date.now()}.${ext}`,
        );
        // Append metadata as a JSON string so backends can pick keys they want.
        form.append("metadata", JSON.stringify(metadata));
        if (uploadFields) {
          for (const [k, v] of Object.entries(uploadFields)) form.append(k, v);
        }
        // Publish fields (caption + host fields): strings as-is (an empty
        // caption IS sent), the rest JSON; null / undefined are skipped (never
        // the literal "null"). A key that would overwrite the file, the metadata
        // or an `uploadFields` entry is skipped with a one-time dev warning.
        for (const [k, v] of Object.entries(fields)) {
          if (v === undefined || v === null) continue;
          if (k === "file" || k === "metadata" || (uploadFields && k in uploadFields)) {
            if (process.env.NODE_ENV !== "production" && !warnedKeysRef.current.has(k)) {
              warnedKeysRef.current.add(k);
              console.warn(
                `story-composer: publish field "${k}" collides with a reserved upload field (file / metadata / uploadFields) and was not sent.`,
              );
            }
            continue;
          }
          form.append(k, typeof v === "string" ? v : JSON.stringify(v));
        }
        xhr.send(form);
      });
    },
    [uploadFields, uploadUrl, uploader, messages],
  );

  return { status, progress, error, upload, cancel, reset };
}

"use client";

import { useCallback, useMemo, useRef, useState } from "react";
import {
  useMediaEditorState,
  type UseMediaEditorStateResult,
} from "../../media-editor";
import type { ComposerMode, ComposerStage, PublishStatus } from "../types";

/**
 * useStoryComposerState — v0.2.0.
 *
 * Composes `useMediaEditorState` (the editor-shaped state machine
 * extracted to media-editor v0.1.0) and augments with story-shaped
 * publish state (publishStatus / uploadProgress / publishError).
 *
 * **Return-shape invariant.** Every v0.1.5 field is preserved with the
 * same identifier and type. New fields are additive:
 *   - All useMediaEditorState fields spread first (state / activeTool /
 *     draft / trim / overlay setters / etc.).
 *   - v0.1.5 fields override / augment: mode (non-null), stage,
 *     visibleModes, setMode (wrapped to preserve switch-during-edit-
 *     resets-stage semantics), markDirty (no-op + dev-warn — isDirty
 *     is now derived).
 *   - Publish-shaped additions tail-spread: publishStatus,
 *     uploadProgress, publishError, and their setters.
 *
 * Consumers who only read v0.1.5 fields keep working unchanged. Consumers
 * who want the new editor-shaped surface (draft, drawingTool, etc.) can
 * access them directly.
 */

const ALL_MODES: ComposerMode[] = ["photo", "video", "text"];

// Single definition lives in ../types (identical union); re-exported so imports
// of `PublishStatus` from this hook keep working.
export type { PublishStatus };

export interface UseStoryComposerStateOptions {
  defaultMode?: ComposerMode;
  hideModes?: ComposerMode[];
  /** Forwarded to useMediaEditorState onDirtyChange. */
  onDirtyChange?: (isDirty: boolean) => void;
}

export interface UseStoryComposerStateResult
  extends Omit<UseMediaEditorStateResult, "setMode"> {
  // === v0.1.5 surface preserved ===
  /** Non-null mode — defaults to first visible mode if editor state is null. */
  mode: ComposerMode;
  stage: ComposerStage;
  visibleModes: ComposerMode[];
  /** v0.1.5 setMode preserved (non-null arg). Resets stage to "capture" + drops draft on a switch-during-edit. */
  setMode: (mode: ComposerMode) => void;
  /**
   * @deprecated v0.2.0 — isDirty is now derived from useMediaEditorState.
   * markDirty(true) is a no-op + dev console.warn. Override the derivation
   * by writing to the editor state directly.
   */
  markDirty: (dirty?: boolean) => void;

  // === v0.2.0 publish-shaped additions ===
  publishStatus: PublishStatus;
  uploadProgress: number;
  publishError: Error | null;
  setPublishStatus: (status: PublishStatus) => void;
  setUploadProgress: (progress: number) => void;
  setPublishError: (error: Error | null) => void;
}

export function useStoryComposerState(
  options: UseStoryComposerStateOptions = {},
): UseStoryComposerStateResult {
  const { defaultMode = "photo", hideModes = [], onDirtyChange } = options;

  const visibleModes = useMemo(
    () => ALL_MODES.filter((m) => !hideModes.includes(m)),
    [hideModes],
  );

  // If the default mode is hidden, fall back to the first visible mode.
  const initialMode = visibleModes.includes(defaultMode)
    ? defaultMode
    : (visibleModes[0] ?? "photo");

  const editor = useMediaEditorState({
    defaultMode: initialMode,
    onDirtyChange,
  });

  // v0.1.5 semantics: switching mode while editing drops back to capture +
  // discards the draft. useMediaEditorState's bare setMode doesn't do that.
  const setMode = useCallback(
    (mode: ComposerMode) => {
      if (mode === editor.state.mode) return;
      if (editor.state.stage === "edit") {
        editor.setStage("capture");
        editor.setDraft(null);
      }
      editor.setMode(mode);
    },
    [editor],
  );

  // markDirty: v0.1.5 manually toggled an isDirty flag. v0.2.0 derives
  // isDirty from useMediaEditorState. Preserved as a no-op + dev warn so
  // existing callers compile and run; visual behavior is governed by the
  // derived value.
  const warnedRef = useRef(false);
  const markDirty = useCallback((dirty: boolean = true) => {
    if (process.env.NODE_ENV === "production") return;
    if (warnedRef.current) return;
    warnedRef.current = true;
    console.warn(
      "useStoryComposerState.markDirty(" +
        dirty +
        ") is a no-op in v0.2.0 — isDirty is derived from useMediaEditorState. " +
        "Drive dirty via setDraft / addTextOverlay / etc. instead. " +
        "Removed in v0.3.0.",
    );
  }, []);

  const [publishStatus, setPublishStatus] = useState<PublishStatus>("idle");
  const [uploadProgress, setUploadProgress] = useState(0);
  const [publishError, setPublishError] = useState<Error | null>(null);

  // Reset clears publish state alongside the editor state.
  const baseReset = editor.reset;
  const reset = useCallback(() => {
    baseReset();
    setPublishStatus("idle");
    setUploadProgress(0);
    setPublishError(null);
  }, [baseReset]);

  return {
    ...editor,
    // v0.1.5 overrides — non-null mode, custom setMode, markDirty shim
    mode: editor.state.mode ?? initialMode,
    stage: editor.state.stage,
    visibleModes,
    setMode,
    markDirty,
    reset,
    // Publish-shaped additions
    publishStatus,
    uploadProgress,
    publishError,
    setPublishStatus,
    setUploadProgress,
    setPublishError,
  };
}

"use client";

import { Loader2, Send, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { ResolvedStoryComposerLabels } from "../types";

export interface ComposerPublishBarProps {
  isPublishing: boolean;
  canPublish: boolean;
  /**
   * Show the publish CTA. Defaults to true. The parent passes false during the
   * capture stage — nothing has been captured yet, so a disabled Publish button
   * just crowds the mode pill on narrow (9:16) widths.
   */
  showPublish?: boolean;
  /**
   * Show the close (X) button. Defaults to true. The parent passes false in the
   * edit stage when the editor renders its own Back arrow in the same corner —
   * Back replaces close (Instagram convention). Edit-only consumers with no
   * capture mode keep close, since there's no Back to fall back to.
   */
  showClose?: boolean;
  labels: ResolvedStoryComposerLabels;
  onPublish: () => void;
  onClose: () => void;
  className?: string;
}

/**
 * Top bar — close (left) + publish CTA (right).
 *
 * Replaces the C3-era right-slot placeholder. Mounted by the parent only
 * when stage === "edit"; the capture stage keeps its own simple top bar.
 */
export function ComposerPublishBar({
  isPublishing,
  canPublish,
  showPublish = true,
  showClose = true,
  labels,
  onPublish,
  onClose,
  className,
}: ComposerPublishBarProps) {
  return (
    <div
      className={cn(
        "absolute top-[max(0.75rem,env(safe-area-inset-top))] left-3 right-3 z-30 flex items-center justify-between",
        className,
      )}
    >
      {showClose ? (
        <Button
          variant="ghost"
          size="icon"
          onClick={onClose}
          aria-label={labels.close}
          disabled={isPublishing}
          // Matches the editor's Back arrow (dark scrim circle) so the
          // top-left action looks identical across capture + edit stages.
          className="rounded-full bg-media-overlay text-media-overlay-foreground backdrop-blur hover:bg-media-overlay hover:text-media-overlay-foreground"
        >
          <X className="size-5" />
        </Button>
      ) : null}

      {showPublish ? (
        <Button
          type="button"
          onClick={onPublish}
          disabled={!canPublish || isPublishing}
          aria-busy={isPublishing}
          className={cn(
            // ms-auto keeps Publish pinned right even when the close button is
            // hidden (otherwise justify-between would pull a lone child left).
            "ms-auto rounded-full gap-1.5 px-4",
            "disabled:opacity-50",
          )}
        >
          {isPublishing ? (
            <>
              <Loader2 className="size-4 animate-spin" />
              <span>{labels.publishing}</span>
            </>
          ) : (
            <>
              <Send className="size-4" />
              <span>{labels.publish}</span>
            </>
          )}
        </Button>
      ) : null}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { AlertTriangle, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { ResolvedStoryComposerLabels } from "../types";

export interface PublishingProgressOverlayProps {
  /** 0..1 — null when indeterminate (no length-computable from server). */
  progress: number | null;
  /**
   * "done" is intentionally NOT a state here — the composer dismisses the
   * overlay on success (onPublished), so only the in-flight + error states
   * render. Kept narrow so the dead "published" arm can't drift back in.
   */
  status: "uploading" | "error";
  /** Error-state body text. Falls back to `labels.uploadFailedBody`. */
  errorMessage?: string;
  labels: ResolvedStoryComposerLabels;
  /** BCP-47 locale for the progress percentage. Invalid tags fall back to "en". */
  locale?: string;
  onRetry?: () => void;
  onCancel?: () => void;
  className?: string;
}

const percentFormats = new Map<string, Intl.NumberFormat>();

/** Cached percent formatter; default "en" (SSR-deterministic), invalid tags fall back to "en". */
function percentFormat(locale: string | undefined): Intl.NumberFormat {
  const key = locale ?? "en";
  let fmt = percentFormats.get(key);
  if (!fmt) {
    const opts: Intl.NumberFormatOptions = {
      style: "percent",
      maximumFractionDigits: 0,
    };
    try {
      fmt = new Intl.NumberFormat(key, opts);
    } catch {
      fmt = new Intl.NumberFormat("en", opts);
    }
    percentFormats.set(key, fmt);
  }
  return fmt;
}

export function PublishingProgressOverlay({
  progress,
  status,
  errorMessage,
  labels,
  locale,
  onRetry,
  onCancel,
  className,
}: PublishingProgressOverlayProps) {
  const percent = percentFormat(locale);
  const cancelRef = useRef<HTMLButtonElement>(null);
  const retryRef = useRef<HTMLButtonElement>(null);

  // The primary control of each state takes focus when the state appears: the
  // content swaps without the overlay unmounting, so nothing else moves focus.
  useEffect(() => {
    const target =
      status === "error"
        ? (retryRef.current ?? cancelRef.current)
        : cancelRef.current;
    target?.focus({ preventScroll: true });
  }, [status]);

  return (
    <div
      className={cn(
        // --media-overlay is black at 0.55 alpha: the blur carries the rest of
        // the old near-opaque scrim so the editor behind stays unreadable.
        "absolute inset-0 z-40 grid place-items-center rounded-[inherit] bg-media-overlay backdrop-blur-md backdrop-brightness-40 text-media-overlay-foreground px-6",
        className,
      )}
    >
      <div className="flex flex-col items-center gap-4 text-center max-w-xs">
        {status === "uploading" ? (
          <>
            <Loader2 className="size-10 animate-spin text-media-overlay-foreground/80" />
            {/* Live region carries the status text only — the percentage below
                is outside it so it is not re-announced on every tick. */}
            <p role="status" className="text-base font-medium">
              {labels.publishing}
            </p>
            {progress !== null ? (
              <div className="w-full">
                <div className="h-1.5 w-full rounded-full bg-media-overlay-foreground/15 overflow-hidden">
                  <div
                    className="h-full bg-media-overlay-foreground transition-[width] duration-150"
                    style={{ width: `${Math.round(progress * 100)}%` }}
                  />
                </div>
                <p className="mt-2 text-xs font-mono tabular-nums text-media-overlay-foreground/80">
                  {percent.format(Math.round(progress * 100) / 100)}
                </p>
              </div>
            ) : null}
            {onCancel ? (
              <Button
                ref={cancelRef}
                variant="ghost"
                onClick={onCancel}
                className="text-media-overlay-foreground/80 hover:bg-media-overlay-foreground/10 hover:text-media-overlay-foreground"
              >
                {labels.discardCancel /* reuses "Keep editing" copy */}
              </Button>
            ) : null}
          </>
        ) : (
          <>
            <AlertTriangle className="size-10 text-warning" />
            <div role="status" className="flex flex-col items-center gap-4">
              <p className="text-base font-medium">{labels.uploadFailedTitle}</p>
              <p className="text-xs text-media-overlay-foreground/80 leading-relaxed">
                {errorMessage ?? labels.uploadFailedBody}
              </p>
            </div>
            <div className="flex items-center gap-2">
              {onCancel ? (
                <Button
                  ref={cancelRef}
                  variant="ghost"
                  onClick={onCancel}
                  className="text-media-overlay-foreground/80 hover:bg-media-overlay-foreground/10 hover:text-media-overlay-foreground"
                >
                  {labels.uploadCancel}
                </Button>
              ) : null}
              {onRetry ? (
                <Button ref={retryRef} onClick={onRetry}>
                  {labels.uploadRetry}
                </Button>
              ) : null}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { Send } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import type {
  PublishFields,
  ResolvedStoryComposerLabels,
  StoryComposerProps,
} from "../types";

export interface PublishDetailsStepProps {
  labels: ResolvedStoryComposerLabels;
  /** BCP-47 locale for the caption counter. Invalid tags fall back to "en". */
  locale?: string;
  /** `caption` prop config; the caption field renders only when set. */
  caption?: StoryComposerProps["caption"];
  value: PublishFields;
  onChange: (next: PublishFields) => void;
  /** Host fields (output of `renderPublishFields`). */
  children?: ReactNode;
  /** Publish enabled (caption rules AND the host's `canPublish`). */
  canPublish: boolean;
  /** Back to the editor. Also fired by Escape inside the step. */
  onBack: () => void;
  onPublish: () => void;
  className?: string;
}

/** First-focus candidates for a step without a caption field. */
const FOCUSABLE_SELECTOR =
  'button:not([disabled]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

const numberFormats = new Map<string, Intl.NumberFormat>();

/** Cached decimal formatter; default "en" (SSR-deterministic), invalid tags fall back to "en". */
function numberFormat(locale: string | undefined): Intl.NumberFormat {
  const key = locale ?? "en";
  let fmt = numberFormats.get(key);
  if (!fmt) {
    try {
      fmt = new Intl.NumberFormat(key);
    } catch {
      fmt = new Intl.NumberFormat("en");
    }
    numberFormats.set(key, fmt);
  }
  return fmt;
}

/**
 * The details step: caption + host fields + Back / Publish. Mounted through
 * media-editor's `overlay` prop, so it sits inside the editor surface (inside
 * the dialog content in dialog presentation). Escape inside the step is Back.
 */
export function PublishDetailsStep({
  labels,
  locale,
  caption,
  value,
  onChange,
  children,
  canPublish,
  onBack,
  onPublish,
  className,
}: PublishDetailsStepProps) {
  const captionId = useId();
  const titleId = useId();
  const counterId = useId();
  const reasonId = useId();
  const captionRef = useRef<HTMLTextAreaElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const [touched, setTouched] = useState(false);
  const text = typeof value.caption === "string" ? value.caption : "";
  const numbers = numberFormat(locale);

  const maxLength = caption?.maxLength;
  const tooLong = maxLength !== undefined && text.length > maxLength;
  const missing = Boolean(caption?.required) && text.trim().length === 0;
  const invalid = tooLong || (missing && touched);
  // Why Publish is disabled, when the caption is the reason.
  const reason = !canPublish
    ? tooLong
      ? labels.captionTooLong(numbers.format(maxLength ?? 0))
      : missing
        ? labels.captionRequired
        : null
    : null;

  useEffect(() => {
    // Caption first; without one, the first host field.
    const target =
      captionRef.current ??
      contentRef.current?.querySelector<HTMLElement>(FOCUSABLE_SELECTOR);
    target?.focus({ preventScroll: true });
  }, []);

  const describedBy =
    [maxLength !== undefined ? counterId : null, reason ? reasonId : null]
      .filter(Boolean)
      .join(" ") || undefined;

  const onKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    // No `defaultPrevented` check: a dialog's dismiss layer calls
    // preventDefault() on every Escape it sees, so the flag cannot tell a
    // host control's own use from the dialog's.
    if (e.key === "Escape") onBack();
  };

  return (
    <section
      aria-labelledby={titleId}
      onKeyDown={onKeyDown}
      className={cn(
        "absolute inset-0 z-40 flex flex-col gap-4 rounded-[inherit] bg-media-overlay px-5 pt-[max(1rem,env(safe-area-inset-top))] pb-[max(1rem,env(safe-area-inset-bottom))] text-media-overlay-foreground backdrop-blur-md backdrop-brightness-40",
        className,
      )}
    >
      <h2 id={titleId} className="text-base font-medium">
        {labels.detailsTitle}
      </h2>

      <div
        ref={contentRef}
        className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto"
      >
        {caption ? (
          <div className="flex flex-col gap-1.5">
            <label htmlFor={captionId} className="text-sm font-medium">
              {labels.captionLabel}
            </label>
            <Textarea
              ref={captionRef}
              id={captionId}
              value={text}
              maxLength={caption.maxLength}
              required={caption.required}
              aria-required={caption.required ? true : undefined}
              aria-invalid={invalid ? true : undefined}
              aria-describedby={describedBy}
              placeholder={caption.placeholder ?? labels.captionPlaceholder}
              onChange={(e) => {
                setTouched(true);
                onChange({ ...value, caption: e.target.value });
              }}
              onBlur={() => setTouched(true)}
              className="min-h-24 border-media-overlay-foreground/30 text-media-overlay-foreground placeholder:text-media-overlay-foreground/70"
            />
            {maxLength !== undefined ? (
              <p
                id={counterId}
                className="text-end font-mono text-xs tabular-nums text-media-overlay-foreground/80"
              >
                {/* bdi isolates the "n / max" run so RTL pages don't reverse it */}
                <bdi dir="ltr">
                  {labels.captionCounter(
                    numbers.format(text.length),
                    numbers.format(maxLength),
                  )}
                </bdi>
              </p>
            ) : null}
          </div>
        ) : null}
        {children}
      </div>

      {reason ? (
        <p id={reasonId} className="text-sm text-media-overlay-foreground/80">
          {reason}
        </p>
      ) : null}

      <div className="flex items-center justify-between gap-2">
        <Button
          type="button"
          variant="ghost"
          onClick={onBack}
          className="text-media-overlay-foreground/80 hover:bg-media-overlay-foreground/10 hover:text-media-overlay-foreground"
        >
          {labels.detailsBack}
        </Button>
        <Button
          type="button"
          onClick={onPublish}
          disabled={!canPublish}
          aria-describedby={reason ? reasonId : undefined}
          className="gap-1.5 rounded-full px-4"
        >
          <Send className="size-4" />
          <span>{labels.publish}</span>
        </Button>
      </div>
    </section>
  );
}
